        "testata": "South China Morning Post",
        "lingua_originale": "en",
        "titolo_orig": "Hong Kong’s Northern Metropolis gains momentum as key project attracts 8 bids",
        "testo_it": "Hong Kong: progetto Northern Metropolis attrae 8 offerte per fase Kam Sheung Road.",
        "priorita": "Bassa",
        "id_gruppo": 18,
